function sliderEl(p={}){const v=p.value??60;return `<input type="range" class="sliderc" min="0" max="100" value="${v}" aria-label="${esc(p.label||'値')}" style="--val:${v}%" oninput="this.style.setProperty('--val',this.value+'%')" ${p.disabled?'disabled':''}>`}
